package edu.uao.yugioh.model; import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*; class CalculadoraCombateTest { @Test void ataqueDirectoReduceLP(){Jugador j=new Jugador("B");new CalculadoraCombate().atacar(new Monstruo("A",2500,1000),null,j);assertEquals(5500,j.getLp());} @Test void ataqueContraDefensaDestruyeSiSuperaDefensa(){ResultadoCombate r=new CalculadoraCombate().atacar(new Monstruo("A",2500,1000),new Monstruo("D",100,2000,Posicion.DEFENSA),new Jugador("B"));assertEquals(0,r.dano());assertEquals("Defensor destruido",r.resultado());} @Test void lpNuncaEsNegativo(){Jugador j=new Jugador("B",100);j.recibirDano(500);assertEquals(0,j.getLp());assertTrue(j.estaDerrotado());} }